            background-color: #f0f8ff;
        }
        #joke {
            font-size: 1.2em;
            margin-top: 20px;
            background: #fff;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
        button {
            padding: 10px 20px;
            font-size: 1em;
            cursor: pointer;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 5px;
        }
        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>

    <h1>Random Joke Generator</h1>
    <button onclick="showRandomJoke()">Click for a Joke</button>
    <div id="joke"></div>

    <script>
        const jokes = [
            "Why don't scientists trust atoms? Because they make up everything.",
            "What do you call fake spaghetti? An impasta.",
            "Why did the scarecrow win an award? Because he was outstanding in his field.",
            "How do you organize a space party? You planet!"
        ];

        function showRandomJoke() {
            const randomIndex = Math.floor(Math.random() * jokes.length);
            document.getElementById("joke").textContent = jokes[randomIndex];
        }
    </script>

</body>
</html>
```

### How it works:
- The HTML has a button that triggers the `showRandomJoke()` function when clicked.
- The JavaScript array `jokes` contains 4 jokes.
- The function selects a random joke from the array and displays it in the `div` with the ID `joke`.

